std::optional<std::string> SetAuxMiniPopupShortcut(Profile* profile,
                                                  const std::string& shortcut) {
  auto* prefs = g_browser_process->local_state();
  if (prefs->IsManagedPreference(kShortcut)) return "Shortcut is managed";
  if (shortcut.size() > 128 ||
      ( !aux::ParseKeyboardShortcut(shortcut) &&
        ui::Command::StringToAccelerator(shortcut).key_code() == ui::VKEY_UNKNOWN))
    return "Shortcut is not valid";
  auto* listener = ui::GlobalAcceleratorListener::GetInstance();
  const bool suspended = listener && listener->IsShortcutHandlingSuspended();
  // Capture suspends global delivery. Registration still must really succeed;
  // preserve that suspension while updating the genuine registered owner.
  if (suspended) listener->SetShortcutHandlingSuspended(false);
  auto& manager = PopupManager::Get();
  auto error = manager.Configure(profile, prefs->GetBoolean(kEnabled), shortcut);
  if (suspended) listener->SetShortcutHandlingSuspended(true);
  if (!error) manager.SetShortcutPreference(prefs, shortcut);
  return error;
}
